package com.sendspindroid.sendspin

import com.sendspindroid.shared.log.Log
import io.mockk.every
import io.mockk.mockkObject
import io.mockk.unmockkAll
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Before
import org.junit.Test

/**
 * Holds [SendspinTimeFilter] to upstream Sendspin/time-filter at 531e270
 * (cpp/sendspin_time_filter.cpp), sample by sample.
 *
 * The vectors come from a line-by-line Python transcription of the C++
 * (IEEE doubles, the C++ operand order, std::round), itself checked bit for
 * bit against aiosendspin's port on every sample that port handles the same
 * way. The input is a Wi-Fi-like session: 30 ppm drift, jittery RTT, late
 * replies, a 40 ms offset step once the forgetting gate is open (sample
 * 120), and three samples the reference skips: max_error 0 and -3, and a
 * time earlier than the last sample.
 *
 * Each row: measurement, max_error, time_added, accepted, then the state
 * after it - offset, drift, offset covariance, offset-drift covariance,
 * drift covariance, use_drift - and compute_server_time(time_added + 1.5 s)
 * and compute_client_time(that + 1234 s).
 */
class SendspinTimeFilterGoldenTest {

    @Before
    fun setUp() {
        mockkObject(Log)
        every { Log.i(any(), any()) } returns 0
    }

    @After
    fun tearDown() {
        unmockkAll()
    }

    private fun <T> field(filter: SendspinTimeFilter, name: String): T =
        @Suppress("UNCHECKED_CAST")
        (SendspinTimeFilter::class.java.getDeclaredField(name).apply { isAccessible = true }.get(filter) as T)

    @Test
    fun `matches the reference sample by sample`() {
        val filter = SendspinTimeFilter()
        VECTORS.trim().lines().forEachIndexed { i, line ->
            val v = line.trim().split(",")
            val accepted = filter.addMeasurement(v[0].toLong(), v[1].toLong(), v[2].toLong())

            val at = "sample $i"
            assertEquals(at, v[3] == "1", accepted)
            assertEquals(at, v[4].toDouble(), field<Double>(filter, "offset"), 0.0)
            assertEquals(at, v[5].toDouble(), field<Double>(filter, "drift"), 0.0)
            assertEquals(at, v[6].toDouble(), field<Double>(filter, "offsetCovariance"), 0.0)
            assertEquals(at, v[7].toDouble(), field<Double>(filter, "offsetDriftCovariance"), 0.0)
            assertEquals(at, v[8].toDouble(), field<Double>(filter, "driftCovariance"), 0.0)
            assertEquals(at, v[9] == "1", field<Boolean>(filter, "useDrift"))
            val probeClient = v[2].toLong() + 1_500_000L
            assertEquals(at, v[10].toLong(), filter.clientToServer(probeClient))
            assertEquals(at, v[11].toLong(), filter.computeClientTime(probeClient + 1_234_000_000L))
        }
    }

